window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f08523cce0f05d15"]={"versions": [{"id": "FIG-f08523cce0f05d15", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Manifest-Spezifikation zur Modellierung von Referenzierungsmechanismen auf Datenelemente (<code>DataPrototype</code>) im Kontext einer Schnittstelle. Das Diagramm spezifiziert die Struktur zur Adressierung von Datenelementen, wenn diese entweder über ein <code>ApplicationDataType</code> oder über einen <code>CppImplementationDataType</code> typisiert sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und zwei Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>DataPrototypeInPortInterfaceRef</code>: Übergeordnete Composite-Klasse zur Referenzierung eines Datenprototyps.\n</li><li><code>DataPrototypeInPortInterfaceInstanceRef</code>: Als pinkfarbener Kasten hervorgehobene Instanzreferenz-Klasse mit dem Typ bzw. Stereotyp <code>AtpInstanceRef</code>. Sie ist über die Kompositionsrolle <code>+dataPrototype</code> mit der Multiplizität <code>0..1</code> angebunden.\n</li><li><code>PortInterfaceElementInImplementationDatatypeRef</code>: Standard-Metaklasse, die über die Kompositionsrolle <code>+elementInImplDatatype</code> mit der Multiplizität <code>0..1</code> an <code>DataPrototypeInPortInterfaceRef</code> angebunden ist.\n</li></ul>\n<p class=\"fig-p\">Beide Rollen sind wechselseitig optional (<code>0..1</code>) als Zielkomponenten aggregiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Sequenzen oder Laufzeitinteraktionen dar. Die Semantik regelt die statische Auflösung von Modellreferenzen: Eine Instanz von <code>DataPrototypeInPortInterfaceRef</code> navigiert entweder über <code>dataPrototype</code> auf eine konkrete Instanzreferenz (<code>DataPrototypeInPortInterfaceInstanceRef</code>) oder über <code>elementInImplDatatype</code> auf ein Modellelement innerhalb eines Implementierungsdatentyps (<code>PortInterfaceElementInImplementationDatatypeRef</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für Manifest-Autoren und Modellierungswerkzeuge der AUTOSAR Adaptive Platform. Die Multiplizitäten <code>0..1</code> an beiden Enden etablieren ein strukturelles Exklusivitäts- bzw. Auswahldesign: Werkzeuge müssen sicherstellen, dass je nach Typisierungskontext (ApplicationDataType vs. CppImplementationDataType) die passende Referenzierungsform belegt wird. <code>AtpInstanceRef</code> signalisiert die Anwendung der AUTOSAR-spezifischen Instanzreferenz-Semantik.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f0a15802d2c1c791", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Manifest-Spezifikation zur Modellierung von Referenzierungsmechanismen auf Datenelemente (<code>DataPrototype</code>) im Kontext eines <code>ServiceInterface</code>. Das Diagramm spezifiziert die Struktur zur Adressierung von Datenelementen bei Typisierung über <code>ApplicationDataType</code> oder <code>CppImplementationDataType</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Klassen und zwei Kompositionen:</p>\n<ul class=\"fig-list\"><li><code>DataPrototypeInServiceInterfaceRef</code>: Übergeordnete Metaklasse.\n</li><li><code>DataPrototypeInServiceInterfaceInstanceRef</code>: Pinkfarben hervorgehobene Klasse, gekennzeichnet mit dem kursiven Kontexttyp <code>DataPrototypeInPortInterfaceInstanceRef</code>. Sie ist über die Komposition <code>+dataPrototype</code> mit der Kardinalität <code>0..1</code> eingebunden.\n</li><li><code>General::PortInterfaceElementInImplementationDatatypeRef</code>: Über den Namensraum <code>General</code> qualifizierte Metaklasse, eingebunden über die Kompositionsrolle <code>+elementInImplDatatype</code> mit Kardinalität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Sequenzen oder Laufzeitinteraktionen dar. Die Semantik regelt die statische Auflösung von Modellreferenzen: Eine Instanz von <code>DataPrototypeInPortInterfaceRef</code> navigiert entweder über <code>dataPrototype</code> auf eine konkrete Instanzreferenz (<code>DataPrototypeInPortInterfaceInstanceRef</code>) oder über <code>elementInImplDatatype</code> auf ein Modellelement innerhalb eines Implementierungsdatentyps (<code>PortInterfaceElementInImplementationDatatypeRef</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Adaptive-Platform-Generatoren und Werkzeugketten. Die Umstellung der Aggregatwurzel auf <code>DataPrototypeInServiceInterfaceRef</code> verankert die Referenzierungssemantik spezifisch im serviceorientierten Kommunikationsmodell der Adaptive Platform (<code>ServiceInterface</code>). Beide Aggregationen sind optional (<code>0..1</code>), sodass entweder die serviceorientierte Instanzreferenz oder der Pfad in den Implementierungsdatentyp gewählt werden kann.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e086c515acdb54cd", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform Manifest-Spezifikation zur Modellierung von Referenzierungsmechanismen auf Datenelemente (<code>DataPrototype</code>) im Kontext eines <code>ServiceInterface</code>. Das Diagramm spezifiziert die Struktur zur Adressierung von Datenelementen bei Typisierung über <code>ApplicationDataType</code> oder <code>CppImplementationDataType</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Klassen und zwei Kompositionen:</p>\n<ul class=\"fig-list\"><li><code>DataPrototypeInServiceInterfaceRef</code>: Übergeordnete Metaklasse.\n</li><li><code>DataPrototypeInServiceInterfaceInstanceRef</code>: Pinkfarben hervorgehobene Klasse, gekennzeichnet mit dem kursiven Kontexttyp <code>DataPrototypeInPortInterfaceInstanceRef</code>. Sie ist über die Kompositionsrolle <code>+dataPrototype</code> mit Multiplizität <code>0..1</code> angebunden.\n</li><li><code>PortInterfaceElementInImplementationDatatypeRef</code>: Unqualifizierte Metaklasse, über die Rolle <code>+elementInImplDatatype</code> mit Multiplizität <code>0..1</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Sequenzen oder Laufzeitinteraktionen dar. Die Semantik regelt die statische Auflösung von Modellreferenzen: Eine Instanz von <code>DataPrototypeInPortInterfaceRef</code> navigiert entweder über <code>dataPrototype</code> auf eine konkrete Instanzreferenz (<code>DataPrototypeInPortInterfaceInstanceRef</code>) oder über <code>elementInImplDatatype</code> auf ein Modellelement innerhalb eines Implementierungsdatentyps (<code>PortInterfaceElementInImplementationDatatypeRef</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Adaptive-Platform-Generatoren und Werkzeugketten. Die Umstellung der Aggregatwurzel auf <code>DataPrototypeInServiceInterfaceRef</code> verankert die Referenzierungssemantik spezifisch im serviceorientierten Kommunikationsmodell der Adaptive Platform (<code>ServiceInterface</code>). Beide Aggregationen sind optional (<code>0..1</code>), sodass entweder die serviceorientierte Instanzreferenz oder der Pfad in den Implementierungsdatentyp gewählt werden kann.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f08523cce0f05d15", "to": "FIG-f0a15802d2c1c791", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die übergeordnete Metaklasse <code>DataPrototypeInPortInterfaceRef</code> wurde in <code>DataPrototypeInServiceInterfaceRef</code> umbenannt.\n</li><li>Die referenzierte Instanzreferenz-Zielklasse mit Stereotyp/Basistyp <code>AtpInstanceRef</code> (<code>DataPrototypeInPortInterfaceInstanceRef</code>) wurde ersetzt durch die Klasse <code>DataPrototypeInServiceInterfaceInstanceRef</code> mit Basis-/Superklasse bzw. Kursiv-Attribut <code>DataPrototypeInPortInterfaceInstanceRef</code>.\n</li><li>Die Metaklasse <code>PortInterfaceElementInImplementationDatatypeRef</code> wurde durch den qualifizierten Paketpfad <code>General::PortInterfaceElementInImplementationDatatypeRef</code> präzisiert.\n</li></ul>"}, {"from": "FIG-f0a15802d2c1c791", "to": "FIG-e086c515acdb54cd", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bei der Klasse <code>PortInterfaceElementInImplementationDatatypeRef</code> wurde das Paketpräfix <code>General::</code> entfernt.\n</li><li>Die Textausrichtung bzw. vertikale Positionierung der Multiplizitätsangaben <code>0..1</code> an beiden Kompositionsenden wurde leicht angepasst.\n</li></ul>"}]};
